$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$specPath = Join-Path $root 'workflow-orbita-kids.json'
$appPath = Join-Path $root 'assets\logos\Logo_Aplicacion.png'
$studioPath = Join-Path $root 'assets\logos\Logo_Empresa.png'
$spec = [IO.File]::ReadAllText($specPath, [Text.Encoding]::UTF8)
$appLogo = [Convert]::ToBase64String([IO.File]::ReadAllBytes($appPath))
$studioLogo = [Convert]::ToBase64String([IO.File]::ReadAllBytes($studioPath))
