.under-flow{display:flex;align-items:center;gap:12px;min-height:32px;padding:0 13px 8px}.legend{display:flex;flex-wrap:wrap;gap:10px 14px}.legend-item{display:flex;align-items:center;gap:5px;color:#aeb9d3;font-size:8px}.legend-item i{width:18px;height:3px;border-radius:3px;background:var(--color);box-shadow:0 0 7px var(--color)}.no-live{margin-left:auto;color:#7e8eae;font-size:8px;white-space:nowrap}
