};
const stageSteps=document.getElementById('steps');
const eventPaths={};let selected=0,playing=false,paused=false,runToken=0,speed=1;let demoAnswer='correct';
function iconFor(i){return ['◉','✦','◆','⇢','▣','＋','✓','↻','✧','▤'][i]}
function renderStages(){stageSteps.innerHTML=stages.map((s,i)=>`<button class="step${i===selected?' active':''}" type="button" data-step="${i}" aria-label="Etapa ${String(i+1).padStart(2,'0')}: ${s.name}"><span class="num">${String(i+1).padStart(2,'0')} · ${iconFor(i)}</span><span class="step-name">${s.name}</span><span class="step-owner">${s.owner.split(' · ')[0]}</span></button>`).join('');stageSteps.querySelectorAll('.step').forEach(b=>b.addEventListener('click',()=>stepTo(+b.dataset.step)))}
function setDetail(i){const s=stages[i];document.getElementById('detailNum').textContent=`ETAPA ${String(i+1).padStart(2,'0')}`;document.getElementById('detailName').textContent=s.name;document.getElementById('detailOwner').textContent=s.owner;document.getElementById('detailStatus').textContent=s.status;document.getElementById('detailDesc').textContent=s.description;document.getElementById('detailInput').textContent=s.input;document.getElementById('detailOutput').textContent=stageOutput(s);document.getElementById('detailOperation').textContent=s.operation}
function stageOutput(s){if(s.id==='stage06')return demoAnswer==='correct'?'13 · respuesta correcta de demo':'12 · respuesta incorrecta de demo';if(s.id==='stage08')return demoAnswer==='correct'?'¡Correcto! · continuar (demo)':'Intenta otra vez · reintento (demo)';return s.output}
function selectStage(i,animate=false){selected=Math.max(0,Math.min(stages.length-1,i));renderStages();setDetail(selected);highlightForStage(selected);if(animate)playEvents(stages[selected].events,++runToken)}
function highlightForStage(i){document.querySelectorAll('.panel,.service-card').forEach(e=>e.classList.remove('active','is-active'));const s=stages[i];const map={stage01:['student'],stage02:['student'],stage03:['student'],stage04:['student','api'],stage05:['api','database','student'],stage06:['student'],stage07:['student','api','database'],stage08:['api','student'],stage09:['database','student'],stage10:['teacher','api']};(map[s.id]||[]).forEach(id=>document.getElementById(id)?.classList.add(id==='api'?'is-active':'active'));Object.values(eventPaths).forEach(x=>{x.path.classList.remove('is-selected');x.label.classList.remove('selected')});s.events.forEach(k=>{eventPaths[k]?.path.classList.add('is-selected');eventPaths[k]?.label.classList.add('selected')});if(i===5||i===6){document.getElementById('taskResult').textContent=demoAnswer==='correct'?'Respuesta de demo: correcta':'Respuesta de demo: incorrecta';document.getElementById('taskBadge').textContent=demoAnswer==='correct'?'13 ✓':'12 ↻'}else if(i<5){document.getElementById('taskResult').textContent='Estado: actividad en progreso';document.getElementById('taskBadge').textContent='DEMO'}else if(i===7){document.getElementById('taskResult').textContent=demoAnswer==='correct'?'¡Respuesta correcta!':'Intenta otra vez';document.getElementById('taskBadge').textContent=demoAnswer==='correct'?'AVANCE':'REINTENTO'}else if(i===8){document.getElementById('taskResult').textContent=demoAnswer==='correct'?'Progreso actualizado (demo)':'Intento registrado (demo)';document.getElementById('taskBadge').textContent='PROGRESO'}}
function portPoint(name){const el=document.querySelector(`[data-port="${name}"]`);if(!el)return null;const r=el.getBoundingClientRect(),b=document.getElementById('flowCanvas').getBoundingClientRect();return{x:r.left+r.width/2-b.left,y:r.top+r.height/2-b.top}}
function pathData(key,d){const a=portPoint(d.from),b=portPoint(d.to);if(!a||!b)return '';const route=d.route||{},dx=b.x-a.x,dy=b.y-a.y;if(Math.abs(dy)>Math.abs(dx)*.65){const dir=Math.sign(dy||1),reach=Math.max(22,Math.min(92,Math.abs(dy)*.42)),side=route.lane||28;return `M${a.x},${a.y} C${a.x+side},${a.y+dir*reach} ${b.x+side},${b.y-dir*reach} ${b.x},${b.y}`}const dir=Math.sign(dx||1),reach=Math.max(32,Math.min(105,Math.abs(dx)*.42)),lane=route.lane||0;return `M${a.x},${a.y} C${a.x+dir*reach},${a.y+lane} ${b.x-dir*reach},${b.y+lane} ${b.x},${b.y}`}
function drawConnections(){const board=document.getElementById('flowCanvas'),svg=document.getElementById('flowSvg');svg.setAttribute('viewBox','0 0 '+board.clientWidth+' '+board.clientHeight);const layer=document.getElementById('pathLayer'),labels=document.getElementById('edgeLabels'),dots=document.getElementById('packetLayer');layer.replaceChildren();labels.replaceChildren();dots.replaceChildren();for(const [key,d] of Object.entries(eventDefs)){const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('id','edge-'+key);p.setAttribute('d',pathData(key,d));p.setAttribute('class','flow-line '+d.kind);layer.appendChild(p);const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('r','5');dot.setAttribute('class','packet '+d.kind);dot.setAttribute('fill',colorFor(d.kind));dots.appendChild(dot);const lab=document.createElement('div');lab.className='edge-label';lab.dataset.edge=key;lab.textContent=d.label;labels.appendChild(lab);eventPaths[key]={path:p,dot,label:lab,def:d};positionLabel(key)}}
function positionLabel(key){const item=eventPaths[key];if(!item)return;const p=item.path;if(!p.getTotalLength())return;const cfg=item.def.route||{},pt=p.getPointAtLength(p.getTotalLength()*.5);item.label.style.left=`${pt.x+(cfg.labelDx||0)}px`;item.label.style.top=`${pt.y+(cfg.labelDy||0)}px`}
function colorFor(k){return({request:'#1DE9B6',backend:'#8A2BE2',database:'#F5D742',teacher:'#C0B2F5',progress:'#1DE9B6',retry:'#C0B2F5'})[k]||'#fff'}
function clearActive(){Object.values(eventPaths).forEach(x=>{x.path.classList.remove('is-active');x.label.classList.remove('active');x.dot.classList.remove('show')});document.querySelectorAll('[data-port]').forEach(p=>p.classList.remove('glow'));document.querySelectorAll('.packet-sending,.packet-receiving').forEach(n=>n.classList.remove('packet-sending','packet-receiving'))}
function wait(ms,token){return new Promise(resolve=>{let elapsed=0,last=performance.now();const tick=()=>{if(token!==runToken){resolve(false);return}const now=performance.now();if(!paused)elapsed+=now-last;last=now;if(elapsed>=ms){resolve(true);return}requestAnimationFrame(tick)};tick()})}
function fly(key,token){const x=eventPaths[key];if(!x)return Promise.resolve(true);const p=x.path,total=p.getTotalLength();if(!total)return Promise.resolve(true);clearActive();x.path.classList.add('is-active');x.label.classList.add('active');x.dot.classList.add('show');const source=document.querySelector('[data-port="'+x.def.from+'"]'),target=document.querySelector('[data-port="'+x.def.to+'"]'),sourceNode=source?.closest('.panel,.service-card'),targetNode=target?.closest('.panel,.service-card');source?.classList.add('glow');sourceNode?.classList.add('packet-sending');if(x.def.db)document.getElementById('dbOperation').textContent=x.def.db;document.getElementById('detailOperation').textContent=x.def.operation;document.getElementById('detailOutput').textContent=x.def.operation;const duration=1200*speed;return new Promise(resolve=>{let last=null,elapsed=0;const frame=t=>{if(token!==runToken){resolve(false);return}if(last===null)last=t;if(!paused)elapsed+=t-last;last=t;const progress=Math.min(1,elapsed/duration),pt=p.getPointAtLength(progress*total);x.dot.setAttribute('cx',pt.x);x.dot.setAttribute('cy',pt.y);if(progress>=1){source?.classList.remove('glow');sourceNode?.classList.remove('packet-sending');target?.classList.add('glow');targetNode?.classList.add('packet-receiving');setTimeout(()=>{x.path.classList.remove('is-active');x.dot.classList.remove('show');resolve(true)},260);return}requestAnimationFrame(frame)};requestAnimationFrame(frame)})}
async function playEvents(events,token){for(const key of events){if(token!==runToken)return;const ok=await fly(key,token);if(!ok)return;await wait(220,token)}if(token===runToken){clearActive();highlightForStage(selected);setDetail(selected)}}
async function run(){if(paused){paused=false;playing=true;return}if(playing)return;if(selected>=stages.length-1)selectStage(-1);playing=true;const token=++runToken;for(let i=selected;i<stages.length;i++){if(token!==runToken)break;while(paused&&token===runToken)await wait(100,token);if(token!==runToken)break;selectStage(i,false);const events=[...stages[i].events];if(i===6&&demoAnswer==='incorrect')events.push('retry');await playEvents(events,token);await wait(330,token)}if(token===runToken){playing=false;paused=false;clearActive()}}
function pause(){if(!playing)return;paused=true;document.getElementById('pauseBtn').classList.add('primary');document.getElementById('playBtn').classList.remove('primary')}
function reset(){runToken++;playing=false;paused=false;clearActive();selectStage(0,false);document.getElementById('dbOperation').textContent='Esperando una operación simulada';document.getElementById('tableState').textContent='ENTIDAD CONCEPTUAL: actividades / resultados / progreso'}
async function stepTo(i){runToken++;playing=false;paused=false;selectStage(i,true);if(i===6&&demoAnswer==='incorrect')await playEvents(['retry'],runToken)}
document.getElementById('playBtn').addEventListener('click',run);document.getElementById('pauseBtn').addEventListener('click',pause);document.getElementById('resetBtn').addEventListener('click',reset);document.getElementById('prevBtn').addEventListener('click',()=>stepTo(Math.max(0,selected-1)));document.getElementById('nextBtn').addEventListener('click',()=>stepTo(Math.min(9,selected+1)));document.getElementById('speed').addEventListener('change',e=>speed=+e.target.value);
document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{demoAnswer=b.dataset.answer;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.toggle('active',x===b));setDetail(selected);highlightForStage(selected)}));
document.getElementById('presentBtn').addEventListener('click',async()=>{document.body.classList.toggle('presentation');if(!document.fullscreenElement){try{await document.documentElement.requestFullscreen()}catch{}}else{try{await document.exitFullscreen()}catch{}}setTimeout(drawConnections,100)});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('presentation');setTimeout(drawConnections,100)});
let activeRoute='dashboard';
function routeFromHash(){const route=location.hash.replace(/^#\/?/,'');return routeNames.includes(route)?route:'dashboard'}
function activateRoute(route){if(!routeNames.includes(route))route='dashboard';activeRoute=route;document.querySelectorAll('.route-view').forEach(view=>view.hidden=view.dataset.view!==route);document.querySelectorAll('.nav a[data-nav]').forEach(link=>{const active=link.dataset.nav===route;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});document.title=`${routeMeta[route][0]} | Órbita Kids`;document.body.dataset.route=route;if(route==='workflow')requestAnimationFrame(()=>{drawConnections();Object.keys(eventPaths).forEach(positionLabel)});window.scrollTo({top:0,behavior:'smooth'})}
function navigateTo(route){if(!routeNames.includes(route))return;if(location.hash!==`#/${route}`)history.pushState({route},'',`#/${route}`);activateRoute(route)}
document.querySelectorAll('.nav a[data-nav]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigateTo(a.dataset.nav)}));document.querySelectorAll('[data-route-link]').forEach(b=>b.addEventListener('click',()=>navigateTo(b.dataset.routeLink)));window.addEventListener('popstate',()=>activateRoute(routeFromHash()));window.addEventListener('hashchange',()=>activateRoute(routeFromHash()));
window.addEventListener('resize',()=>{if(activeRoute==='workflow'){drawConnections();Object.keys(eventPaths).forEach(positionLabel)}});window.addEventListener('load',()=>{renderStages();setDetail(0);drawConnections();highlightForStage(0)});new ResizeObserver(()=>{if(activeRoute==='workflow'){drawConnections();Object.keys(eventPaths).forEach(positionLabel)}}).observe(document.getElementById('flowCanvas'));activateRoute(routeFromHash());
async function runSelfTest(){const r=[];const check=(name,ok)=>r.push({name,ok:!!ok});const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));for(const route of routeNames){document.querySelector('.nav a[data-nav="'+route+'"]').click();const view=document.querySelector('[data-view="'+route+'"]'),heading=view.querySelector('h1');check('navegación '+route+' ['+document.documentElement.scrollWidth+'/'+window.innerWidth+']',activeRoute===route&&location.hash==='#/'+route&&!view.hidden&&document.querySelector('.nav a[data-nav="'+route+'"]').getAttribute('aria-current')==='page'&&document.documentElement.scrollWidth<=window.innerWidth&&!!heading&&(route==='workflow'?heading.textContent.includes('Workflow'):heading.textContent===routeMeta[route][0]))}navigateTo('workflow');history.back();await delay(90);check('historial atrás restaura la vista anterior',activeRoute==='documentacion');history.forward();await delay(90);check('historial adelante restaura Workflow',activeRoute==='workflow');await delay(100);drawConnections();check('modelo Archify con 10 etapas',spec.nodes.length===10);check('10 botones de etapa visibles',document.querySelectorAll('.step').length===10);for(let i=0;i<10;i++){document.querySelector('[data-step="'+i+'"]').click();check('selección etapa '+(i+1),selected===i&&document.getElementById('detailNum').textContent==='ETAPA '+String(i+1).padStart(2,'0'))}for(const [key,x] of Object.entries(eventPaths))check('ruta '+key+' ('+x.path.getTotalLength().toFixed(1)+'px)',x.path.getTotalLength()>10);document.querySelector('[data-answer="incorrect"]').click();selectStage(6,false);check('rama incorrecta muestra reintento',stageOutput(stages[7]).includes('Intenta otra vez'));document.querySelector('[data-answer="correct"]').click();check('rama correcta muestra avance',stageOutput(stages[7]).includes('¡Correcto!'));document.getElementById('speed').value='0.5';document.getElementById('speed').dispatchEvent(new Event('change'));check('velocidad 2x aplicada',speed===0.5);reset();const runPromise=run();let waited=0;while(!eventPaths['activity-request'].dot.classList.contains('show')&&waited<6000){await delay(35);waited+=35}const dot=eventPaths['activity-request'].dot;const active=dot.classList.contains('show');if(active){while(dot.getAttribute('cx')===null)await delay(25);pause();const before=[dot.getAttribute('cx'),dot.getAttribute('cy')];await delay(450);const after=[dot.getAttribute('cx'),dot.getAttribute('cy')];check('pausa conserva ubicación del paquete',before[0]===after[0]&&before[1]===after[1]);paused=false}else check('pausa conserva ubicación del paquete',false);let completed=false;await Promise.race([runPromise.then(()=>completed=true),delay(18000)]);check('reproducción recorre las diez etapas',completed&&selected===9&&!playing);reset();check('reinicio regresa a etapa 1',selected===0&&!playing);document.body.dataset.selftest=r.every(x=>x.ok)?'PASS':'FAIL';document.title=document.body.dataset.selftest+' · '+document.title;document.body.insertAdjacentHTML('beforeend','<pre id="test-results" style="position:fixed;z-index:100;right:8px;bottom:8px;max-width:480px;max-height:40vh;overflow:auto;padding:12px;background:#071018;border:2px solid '+(r.every(x=>x.ok)?'#1de9b6':'#f56')+';color:#fff;font:12px monospace">'+JSON.stringify(r,null,2)+'</pre>')}
if(new URLSearchParams(location.search).has('selftest')){window.requestAnimationFrame=cb=>setTimeout(()=>cb(performance.now()),8);window.addEventListener('load',()=>setTimeout(runSelfTest,80))}
</script>
</body></html>
'@
$html = $template.Replace('__APP_LOGO__', $appLogo).Replace('__STUDIOS_LOGO__', $studioLogo).Replace('__WORKFLOW_SPEC__', $spec).Replace('__SPEC_URI__', [Uri]::EscapeDataString($spec))
$out = Join-Path $root 'workflow-orbita-kids.html'
[IO.File]::WriteAllText($out, $html, (New-Object Text.UTF8Encoding($false)))
Write-Output "Dashboard creado: $out"
